                for (axis,v) in [("x",w.report_cr_normal.x),("y",w.report_cr_normal.y)] {let [hi,lo]=v.to_words();write!(s,"{p}normal.{axis}={hi:08x}{lo:08x};").unwrap();}
                write!(s,"{p}own_body_present={};{p}other_body_present={};",(r.shape!=NONE && w.shape(r.shape).body!=NONE) as u32,(r.other!=NONE && w.shape(r.other).body!=NONE) as u32).unwrap();
